import re, glob

files = sorted(glob.glob("/tmp/ajc_head/*.lean"))

def strip_comments(text):
    out = []
    i = 0
    n = len(text)
    depth = 0
    while i < n:
        if text[i:i+2] == '/-':
            depth += 1
            i += 2
            while i < n and depth > 0:
                if text[i:i+2] == '/-':
                    depth += 1
                    i += 2
                elif text[i:i+2] == '-/':
                    depth -= 1
                    i += 2
                else:
                    i += 1
            continue
        out.append(text[i])
        i += 1
    text2 = ''.join(out)
    lines = []
    for line in text2.split('\n'):
        idx = line.find('--')
        if idx != -1:
            line = line[:idx]
        lines.append(line)
    return '\n'.join(lines)

for f in files:
    text = open(f, encoding='utf-8').read()
    stripped = strip_comments(text)
    lines = stripped.split('\n')
    starts = []
    for idx, line in enumerate(lines):
        m = re.match(r'^(theorem|lemma|def|instance|class|structure|abbrev|noncomputable\s+def|noncomputable\s+instance|private\s+def|private\s+theorem|@\[)', line)
        if m:
            starts.append(idx)
